mapper.select:
/* com.portal.system.menu.MenuManageMapper.selectLastMenuURL */
SELECT URL
  FROM LETTNPROGRMLIST
 WHERE PROGRM_FILE_NM = (
       SELECT PROGRM_FILE_NM
         FROM LETTNMENUINFO
        WHERE MENU_NO = #{menuNo}
 )

/* com.portal.system.menu.MenuManageMapper.selectLastMenuNo */
SELECT MIN(MENU_NO)
  FROM LETTNMENUINFO
 WHERE UPPER_MENU_NO = #{menuNo}
   AND MENU_ORDR = (
       SELECT MIN(b.MENU_ORDR)
         FROM LETTNMENUCREATDTLS a
        INNER JOIN LETTNMENUINFO b
           ON a.MENU_NO = b.MENU_NO
        WHERE a.AUTHOR_CODE = (
              SELECT AUTHOR_CODE
                FROM LETTNEMPLYRSCRTYESTBS
               WHERE SCRTY_DTRMN_TRGET_ID = #{tempValue}
        )
          AND b.UPPER_MENU_NO = #{menuNo}
   )

/* com.portal.system.menu.MenuManageMapper.selectLastMenuNoCnt */
SELECT COUNT(MENU_NO)
  FROM LETTNMENUINFO
 WHERE UPPER_MENU_NO = #{menuNo}
   AND MENU_ORDR = (
       SELECT MIN(b.MENU_ORDR)
         FROM LETTNMENUCREATDTLS a
        INNER JOIN LETTNMENUINFO b
           ON a.MENU_NO = b.MENU_NO
        WHERE a.AUTHOR_CODE = (
              SELECT AUTHOR_CODE
                FROM LETTNEMPLYRSCRTYESTBS
               WHERE SCRTY_DTRMN_TRGET_ID = #{tempValue}
        )
          AND b.UPPER_MENU_NO = #{menuNo}
   )
